import assert from 'node:assert/strict'
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { evaluateGraphIntegrity } from '../app/scripts/generateCurriculumQualityStatus.ts'
const read = (p:string) => JSON.parse(readFileSync(p,'utf8'))
const sha = (p:string) => createHash('sha256').update(readFileSync(p)).digest('hex')
const nativePaths=['app/scripts/lib/skillGraphIntegrity.ts','app/scripts/auditTransitiveMinimality.ts',
 'app/scripts/generateCurriculumQualityStatus.ts','app/scripts/config/curriculum-maturity-floor-policy.json']
const implementations=nativePaths.map(path=>({path,sha256:sha(path)}))
const proof=read('tmp/global-orientation-cycle-analysis.json')
const original=proof.catalogSources.map((s:any)=>{assert.equal(sha(s.path),s.sha256);return read(s.path)})
const candidate=read('tmp/global-orientation-cycle-candidates.json')
const floors=read(nativePaths[3]).floors
const cycleKeys=proof.beforeComponents.atomic.flat()
const catalogs=[original,candidate].map(docs=>docs.map((d:any,i:number)=>({...d,sourceFile:proof.catalogSources[i].path})))
const results=[]
for(let i=0;i<original.length;i++) {
 const runs=[]
 for(let s=0;s<2;s++) {
  const r=evaluateGraphIntegrity(catalogs[s][i],catalogs[s]);const g=r.graphIntegrity!
  runs.push({scenario:s?'proposed-five-operations':'current-source',cqrRuleId:r.id,cqrStatus:r.status,
   checks:g.checks,checkedRules:g.checkedRules,metrics:g.metrics,
   checkedGoalKeyCount:g.checkedGoalKeys.length,
   checkedGoalKeysSha256:createHash('sha256').update(JSON.stringify(g.checkedGoalKeys)).digest('hex'),
   includedCycleKeys:cycleKeys.filter((k:string)=>g.checkedGoalKeys.includes(k)),
   cycleFindings:g.findings.filter(x=>['G06','G07','G15','G42'].includes(x.ruleId)),
   otherFindingCounts:Object.fromEntries([...new Set(g.findings.map(x=>x.ruleId))].map(id=>[id,g.findings.filter(x=>x.ruleId===id).length])),
  })
 }
 assert.equal(runs[0].checkedGoalKeysSha256,runs[1].checkedGoalKeysSha256)
 results.push({landscapeId:original[i].landscapeId,title:original[i].title,
   source:proof.catalogSources[i],protectedFloor:floors.find((f:any)=>f.landscapeId===original[i].landscapeId)??null,runs})
 console.log(JSON.stringify({title:original[i].title,protected:!!results.at(-1)!.protectedFloor,
  cycles:runs.map(r=>r.checks.filter(c=>['G15','G42'].includes(c.id))),cqr:runs.map(r=>r.cqrStatus)}))
}
for(const b of implementations)assert.equal(sha(b.path),b.sha256)
for(const b of proof.catalogSources)assert.equal(sha(b.path),b.sha256)
const out={status:'actual-native-cqr001-before-and-five-operation-hypothesis-no-application',
 implementations,sourceBindings:proof.catalogSources,results,
 fullCqrGeneratorRun:false,sourceApplied:false,maturityClaimed:false}
const reinsertionChecks=[]
for(const op of proof.operations.slice(0,3)) {
 const docs=structuredClone(catalogs[1])
 const i=docs.findIndex((d:any)=>d.landscapeId===op.source.landscapeId)
 const goal=docs[i].goals.find((g:any)=>g.id===op.guardGoalId)
 goal.requires=op.guardRequiresBefore
 const result=evaluateGraphIntegrity(docs[i],docs)
 for(const id of ['G15','G42'])assert.equal(result.graphIntegrity!.checks.find(c=>c.id===id)?.status,'fail')
 reinsertionChecks.push({operationId:op.operationId,cqrStatus:result.status,
  checks:result.graphIntegrity!.checks.filter(c=>['G15','G42'].includes(c.id)),
  cycleFindings:result.graphIntegrity!.findings.filter(c=>['G15','G42'].includes(c.ruleId))})
}
Object.assign(out,{reinsertionNegativeControls:reinsertionChecks})
for(const b of implementations)assert.equal(sha(b.path),b.sha256)
writeFileSync('tmp/global-orientation-cycle-native.json',JSON.stringify(out,null,2)+'\n')
